def add(n,q,o,a,t,obs,st,steps,end,crop=None,reason='',tip='조건과 구하는 대상을 먼저 확인하고, 계산 결과를 원래 자료나 도형의 성질에 다시 대입하여 점검하세요.'):
 r=5 if n%2 else 6;seq=len(D[r])+1;o=o.split('|');aa=a if isinstance(a,list) else [a];steps=steps.split('|')
 h=f'**[관찰 단계]**\n{obs}\n\n**[개념 연결]**\n{C[t]}\n\n**[과정 추론]**\n{st} {tip}\n\n**[결론 유도]**\n{end}'
 e='## 문제 풀이\n**문제 내용:** '+q+'\n\n'+'\n'.join(f'- 보기 ${i+1}$: {v}' for i,v in enumerate(o))+'\n\n### 이 문제를 풀기 위해 무엇을 알아야 할까요? (핵심 개념 체크)\n'+C[t]+'\n\n### 어떻게 접근해야 할까요? (풀이 전략)\n'+st+'\n\n### 차근차근 풀어봅시다! (단계별 상세 풀이)\n'+'\n\n'.join(f'**단계 ${i+1}$:** {v}' for i,v in enumerate(steps))+'\n\n정답은 '+', '.join(f'보기 ${a}$ ({o[a-1]})' for a in aa)+'입니다.\n\n### 이런 실수는 하지 마세요! / 더 알아두면 좋아요 (주의점 및 팁)\n'+tip
 D[r].append(dict(question=q,options=o,answer=o[a-1] if len(aa)==1 else [o[j-1] for j in aa],hint=h,explanation=e))
 M[r].append(dict(number=seq,sourceNumber=n,topic=('삼각비' if n<=14 else '원의 성질' if n<=38 else '통계'),correctOptionNumbers=aa,imagePath=f'assets/q{seq:02}.png' if crop else None,sourceImagePath=f'assets/source-q{seq:02}.png',replaced=bool(reason),replacementReason=reason,crop=crop,verification=steps))
add(1,r'그림과 같이 모양이 같고 크기가 다른 세 직각삼각형을 한 꼭짓점 $A$에 겹쳐 놓았다. 다음 중 옳지 않은 것은?',r'$\frac{DE}{AD}=\frac{FG}{AF}$|$\frac{AC}{AB}=\frac{AG}{AF}$|$\sin A=\frac{DE}{AD}$|$\cos A=\frac{AC}{AB}$|$\tan A=\frac{AG}{FG}$',5,'ratio','각 삼각형에서 기준각에 붙은 변과 맞은편 변, 빗변은 어디인가요?','세 삼각형은 닮았으므로 대응변의 비가 같다는 점과 삼각비의 정의를 함께 적용하세요.',r'모든 삼각형의 각 $A$가 같으므로 $\frac{DE}{AD}=\frac{FG}{AF}=\sin A$, $\frac{AC}{AB}=\frac{AG}{AF}=\cos A$입니다.|탄젠트는 높이를 밑변으로 나누므로 $\tan A=\frac{FG}{AG}$입니다. 보기 $5$는 분자와 분모가 바뀌었습니다.','어떤 보기에서 두 직각변의 순서가 뒤집혔나요?',(1,166,254,331,359))
add(2,r'그림과 같이 모양이 같고 크기가 다른 세 직각삼각형을 한 꼭짓점 $A$에 겹쳐 놓았다. $\cos F$의 값으로 적절한 것을 모두 고르면? (정답 $2$개)',r'$\frac{FG}{AF}$|$\frac{BC}{AB}$|$\frac{AG}{AF}$|$\frac{AC}{AB}$|$\frac{FG}{AG}$',[1,2],'ratio','기준각이 공통 꼭짓점이 아니라 위쪽 꼭짓점이라는 점을 확인했나요?','큰 삼각형에서 코사인을 구한 뒤 다른 삼각형의 대응각으로 옮겨 보세요.',r'$\cos F=\frac{FG}{AF}$입니다. 닮음에서 $\angle F=\angle B$이므로 $\cos F=\cos B=\frac{BC}{AB}$입니다.|보기 $3,4$는 $\cos A$이고 보기 $5$는 $\tan A$입니다.','같은 코사인 값을 나타내는 두 비는 무엇인가요?',(1,166,254,331,359))
add(3,r'그림의 직각삼각형에서 $\angle C=90^\circ$, $AB=7$, $BC=5$일 때, $\frac{\cos A}{\tan A}$의 값은?',r'$\frac4{35}$|$\frac{3\sqrt6}{14}$|$\frac{2\sqrt6}{7}$|$\frac{24}{35}$|$\frac{5\sqrt6}{12}$',4,'ratio','미지의 직각변을 피타고라스 정리로 구할 수 있나요?','코사인과 탄젠트를 각각 변의 비로 표현한 뒤 분수 나눗셈을 하세요.',r'$AC=\sqrt{7^2-5^2}=2\sqrt6$입니다.|$\cos A=\frac{2\sqrt6}{7}$, $\tan A=\frac5{2\sqrt6}$입니다.|따라서 $\frac{\cos A}{\tan A}=\frac{2\sqrt6}{7}\times\frac{2\sqrt6}{5}=\frac{24}{35}$입니다.','나누는 분수를 뒤집어 곱했나요?',(1,154,909,344,1030))
add(4,r'다음을 올바르게 계산한 값은? $\frac{\sin30^\circ}{\cos45^\circ}-\tan0^\circ\sin60^\circ+\tan45^\circ\cos60^\circ$',r'$\frac{\sqrt2}{2}$|$1$|$\frac{1+\sqrt2}{2}$|$\frac{1+\sqrt3}{2}$|$\frac{1+\sqrt2-\sqrt3}{2}$',3,'ratio','영이 되는 삼각비와 특수각의 값을 먼저 확인했나요?','곱과 나눗셈을 먼저 계산하고 같은 분모로 더하세요.',r'$\frac{\sin30^\circ}{\cos45^\circ}=\frac{1/2}{\sqrt2/2}=\frac{\sqrt2}{2}$입니다.|$\tan0^\circ=0$, $\tan45^\circ=1$, $\cos60^\circ=\frac12$이므로 전체 값은 $\frac{\sqrt2}{2}+\frac12=\frac{1+\sqrt2}{2}$입니다.','영인 항을 정리한 뒤 남은 두 항의 합은 얼마인가요?')
add(5,r'세 내각의 크기의 비가 $9:10:17$인 삼각형에서 가장 작은 내각을 $\angle A$라 할 때, $\sin A:\cos A:\tan A$의 비는?',r'$1:1:\sqrt2$|$\sqrt2:1:1$|$2:1:\sqrt3$|$1:2:\sqrt3$|$9:10:17$',1,'ratio','비의 합과 삼각형의 내각의 합을 연결할 수 있나요?','비의 한 단위에 해당하는 각을 구한 뒤 가장 작은 각의 삼각비를 비교하세요.',r'한 단위는 $\frac{180^\circ}{9+10+17}=5^\circ$이므로 $A=45^\circ$입니다.|$\sin A:\cos A:\tan A=\frac{\sqrt2}{2}:\frac{\sqrt2}{2}:1$입니다.|세 항에 $\sqrt2$를 곱하면 $1:1:\sqrt2$입니다.','각의 비와 삼각비의 비를 구분했나요?')
add(6,r'$AB=3\sqrt2\,cm$, $\angle B=45^\circ$, $\angle C=60^\circ$인 $\triangle ABC$의 넓이는?',r'$\frac{6+\sqrt2}{2}\,cm^2$|$\frac{9+3\sqrt2}{2}\,cm^2$|$\frac{6+\sqrt3}{2}\,cm^2$|$\frac{9+3\sqrt3}{2}\,cm^2$|$(6+2\sqrt3)\,cm^2$',4,'area','수선을 내리면 주어진 빗변과 각으로 높이를 구할 수 있나요?','높이와 밑변의 두 조각을 차례로 구한 뒤 삼각형의 넓이를 구하세요.',r'$A$에서 $BC$에 내린 수선의 발을 $H$라 하면 $AH=BH=3$입니다.|$HC=\frac{3}{\tan60^\circ}=\sqrt3$이므로 $BC=3+\sqrt3$입니다.|넓이는 $\frac12\times(3+\sqrt3)\times3=\frac{9+3\sqrt3}{2}\,cm^2$입니다.','밑변의 두 조각을 모두 더했나요?',(1,571,831,718,933))
add(7,r'반지름이 $1$인 사분원 그림을 이용하여 $\sin48^\circ+\cos42^\circ$를 계산하면?',r'$1.338$|$1.412$|$1.486$|$1.78$|$1.854$',3,'ratio','단위원에서 세로 길이와 기준각의 사인을 연결할 수 있나요?','두 각이 여각인지 확인하고 그림에서 같은 값을 두 번 사용하세요.',r'$\sin48^\circ=0.743$이고 $\cos42^\circ=\sin48^\circ$입니다.|합은 $0.743+0.743=1.486$입니다.','가로 길이가 아닌 세로 길이를 읽었나요?',(2,167,139,329,286))
add(8,r'$\angle A=90^\circ$인 직각삼각형 $ABC$에서 $AD\perp BC$, $DE\perp AC$이다. $BC=12$, $\angle B=60^\circ$일 때, $CE$의 길이는?',r'$\frac{\sqrt3}{2}$|$\frac{3\sqrt3}{2}$|$\frac{5\sqrt3}{2}$|$\frac{7\sqrt3}{2}$|$\frac{9\sqrt3}{2}$',5,'ratio','두 수선을 그린 작은 삼각형이 원래 삼각형과 어떤 각을 공유하나요?','공통 예각을 기준으로 큰 삼각형에서 구한 변을 작은 삼각형에 차례로 사용하세요.',r'$\angle C=30^\circ$, $AC=12\sin60^\circ=6\sqrt3$입니다.|$\triangle ADC$에서 $CD=AC\cos30^\circ=9$입니다.|$\triangle CDE$에서 $CE=CD\cos30^\circ=\frac{9\sqrt3}{2}$입니다.','각 단계에서 빗변이 어느 선분인지 다시 확인했나요?',(2,172,551,333,657))
add(9,r'그림의 정육면체에서 $\angle DFH=x^\circ$일 때, $\cos x^\circ$의 값은?',r'$\frac12$|$\frac{\sqrt2}{2}$|$\frac{\sqrt3}{2}$|$\frac{\sqrt3}{3}$|$\frac{\sqrt6}{3}$',5,'ratio','밑면 대각선과 공간 대각선이 포함된 직각삼각형을 찾았나요?','모서리 길이를 한 문자로 놓고 피타고라스 정리를 두 번 사용하세요.',r'한 모서리를 $a$라 하면 $FH=\sqrt2a$, $DH=a$, $DF=\sqrt3a$입니다.|$\cos x^\circ=\frac{FH}{DF}=\frac{\sqrt2}{\sqrt3}=\frac{\sqrt6}{3}$입니다.','코사인의 분자에 기준각과 붙은 직각변을 썼나요?',(2,171,879,324,1030))
add(10,r'길이가 $10\,m$이고 경사각이 $35^\circ$인 에스컬레이터에서 높이 $BC$를 삼각비로 바르게 나타낸 것은? (단위: $m$)',r'$10\tan35^\circ$|$\frac{\tan35^\circ}{10}$|$\frac1{\tan35^\circ}$|$10\sin35^\circ$|$\frac{10}{\sin35^\circ}$',4,'ratio','에스컬레이터 길이는 빗변인가요 높이인가요?','맞은편 변을 빗변으로 나누는 삼각비를 사용하세요.',r'$\sin35^\circ=\frac{BC}{10}$입니다.|따라서 $BC=10\sin35^\circ\,m$입니다.','전체 길이보다 높이가 작아지는 식인가요?',(2,561,158,719,269))
add(11,r'바다 위의 배 $A$를 두 등대 $B,C$에서 관찰하였다. $BC=100\,m$, $\angle ABC=75^\circ$, $\angle ACB=60^\circ$일 때, 배와 등대 $B$ 사이의 거리는?',r'$50\sqrt2\,m$|$50\sqrt3\,m$|$50\sqrt6\,m$|$100\sqrt2\,m$|$100\sqrt3\,m$',3,'ratio','나머지 내각을 구하면 특수각을 사용할 수 있나요?','공통 높이를 두 삼각형에서 다르게 표현하여 구하는 변을 찾으세요.',r'$\angle A=45^\circ$입니다. $B$에서 $AC$에 내린 높이는 $100\sin60^\circ=50\sqrt3$입니다.|이 높이는 $AB\sin45^\circ$이기도 하므로 $AB=\frac{50\sqrt3}{\sqrt2/2}=50\sqrt6\,m$입니다.','어느 변을 구하라는 문제인지 확인했나요?',(2,588,601,703,736))
add(12,r'그림에서 $AB=9\,cm$, $BC=12\,cm$, $AD=3\sqrt3\,cm$, $DC=6\,cm$, $\angle ABC=60^\circ$, $\angle ADC=150^\circ$이다. 사각형 $ABCD$의 넓이는?',r'$\frac{63}{2}\,cm^2$|$\frac{63\sqrt3}{2}\,cm^2$|$\frac{81}{2}\,cm^2$|$\frac{81\sqrt3}{2}\,cm^2$|$\frac{27+54\sqrt3}{2}\,cm^2$',2,'area','대각선으로 나눈 두 삼각형에서 두 변과 끼인각이 주어졌나요?','삼각형 둘의 넓이를 계산하여 합하세요.',r'$\triangle ABC$의 넓이는 $\frac12\times9\times12\times\sin60^\circ=27\sqrt3$입니다.|$\triangle ADC$의 넓이는 $\frac12\times3\sqrt3\times6\times\sin150^\circ=\frac{9\sqrt3}{2}$입니다.|합은 $\frac{63\sqrt3}{2}\,cm^2$입니다.','공통 대각선 양쪽의 넓이를 모두 포함했나요?',(2,570,885,725,1008))
add(13,r'한 변의 길이가 $3\sqrt2\,cm$이고 넓이가 $9\sqrt3\,cm^2$인 마름모의 내각 중 가장 큰 각은?',r'$60^\circ$|$90^\circ$|$120^\circ$|$135^\circ$|$150^\circ$',3,'area','마름모의 높이를 한 변과 내각의 사인으로 나타낼 수 있나요?','넓이에서 사인 값을 구한 뒤 이웃한 내각의 합을 이용하세요.',r'예각을 $\theta$라 하면 넓이는 $(3\sqrt2)^2\sin\theta=18\sin\theta$입니다.|$\sin\theta=\frac{\sqrt3}{2}$이므로 예각은 $60^\circ$입니다. 이웃한 내각의 합이 $180^\circ$이므로 가장 큰 각은 $120^\circ$입니다.','예각이 아니라 가장 큰 내각을 선택했나요?')
add(14,r'한 변이 $4\,cm$인 정사각형 $ABCD$에서 $AB,BC$의 중점을 각각 $M,N$이라 한다. $\angle MDN=x$일 때, $\cos x$의 값은?',r'$\frac45$|$\frac34$|$\frac35$|$\frac14$|$\frac25$',1,'ratio','각을 이루는 두 선분의 길이와 두 중점 사이 길이를 구할 수 있나요?','두 선분이 같은 이등변삼각형에서 밑변에 수선을 내려 코사인을 구하거나, 한 선분에 다른 점을 정사영하세요.',r'$DM=DN=\sqrt{4^2+2^2}=2\sqrt5$, $MN=2\sqrt2$입니다.|$M$에서 $DN$에 내린 수선의 발을 $H$, $DH=t$라 하면 $DM^2-t^2=MN^2-(DN-t)^2$입니다.|$20-t^2=8-(2\sqrt5-t)^2$에서 $t=\frac8{\sqrt5}$. 따라서 $\cos x=\frac{DH}{DM}=\frac45$입니다.','직각삼각형에서 빗변과 정사영 길이의 비를 구했나요?',(3,192,392,320,534))
add(15,r'원 $O$의 중심에서 두 현 $AB,CD$까지의 거리가 같다. $CD=6\,cm$, $\angle BAO=30^\circ$일 때, 반지름은?',r'$2\sqrt3\,cm$|$\frac72\,cm$|$4\,cm$|$3\sqrt2\,cm$|$\frac92\,cm$',1,'chord','중심에서 거리가 같은 두 현의 길이는 같나요?','현의 절반과 반지름으로 만든 직각삼각형에서 코사인을 사용하세요.',r'$AB=CD=6\,cm$이므로 $AB$의 절반은 $3\,cm$입니다.|반지름을 $r$라 하면 $\cos30^\circ=\frac3r$이므로 $r=2\sqrt3\,cm$입니다.','현 전체가 아닌 절반 길이를 사용했나요?',(3,175,810,322,948))
add(16,r'원 $O$의 중심에서 현 $AB,CD$에 내린 수선의 발이 각각 $M,N$이다. $OM=ON$일 때, 옳지 않은 것은?',r'$AM=BM$|$\triangle OAM\cong\triangle OCN$|$AB=CD$|$ON=DN$|$CD=2BM$',4,'chord','현의 절반과 중심에서 현까지 거리는 같은 종류의 길이인가요?','수선의 이등분 성질과 직각삼각형의 빗변·한 변 합동을 이용하세요.',r'$AM=BM$, $CN=DN$이며 $OA=OC$, $OM=ON$이므로 $\triangle OAM\cong\triangle OCN$입니다.|따라서 $AB=CD=2BM$입니다. 그러나 중심에서 현까지 거리 $ON$과 현의 절반 $DN$이 같다는 조건은 없습니다.','합동이나 이등분으로 보장되지 않는 등식은 무엇인가요?',(3,576,160,716,300))
add(17,r'호 $AB$는 원의 일부이다. $AB\perp CD$, $AD=DB$, $AB=10\,cm$, $CD=2\,cm$일 때, 이 원의 반지름은?',r'$6\,cm$|$\frac{25}{4}\,cm$|$7\,cm$|$\frac{29}{4}\,cm$|$\frac{31}{4}\,cm$',4,'chord','현에서 호의 꼭대기까지의 높이와 반지름의 관계를 찾았나요?','현의 수직이등분선 위에 중심을 잡고 반지름으로 피타고라스 식을 세우세요.',r'반지름을 $r$라 하면 현의 절반은 $5$, 중심에서 현까지의 거리는 $r-2$입니다.|$r^2=5^2+(r-2)^2$에서 $4r=29$이므로 $r=\frac{29}{4}\,cm$입니다.','제곱항이 없어지고 남는 식을 풀었나요?',(3,543,558,743,625))
add(18,r'$\triangle ABC$는 원 $O$에 외접하고 $D,E,F$는 접점이다. $AB=8\,cm$, $BC=11\,cm$, $CA=9\,cm$일 때, $CF$의 길이는?',r'$5\,cm$|$6\,cm$|$7\,cm$|$\frac{11}{2}\,cm$|$\frac{13}{2}\,cm$',2,'tangent','각 꼭짓점에서 두 접점까지 같은 길이를 표시했나요?','구하는 접선 길이를 문자로 놓고 나머지 조각들을 변의 차로 나타내세요.',r'$CF=CE=x$라 하면 $AF=AD=9-x$, $BE=BD=11-x$입니다.|$AB=(9-x)+(11-x)=8$에서 $2x=12$, $x=6\,cm$입니다.','세 변의 조건을 모두 만족하는 길이인가요?',(3,542,930,748,1064))
add(19,r'지름 $AB$의 양 끝점에서 그은 접선과 원 위의 점 $P$에서 그은 접선이 만나는 점이 각각 $C,D$이다. 다음 중 옳지 않은 것은?',r'$AC=PC$|$BD=PD$|$\angle COD=90^\circ$|$\angle AOC=\angle BOD$|$\angle BDO=\angle PDO$',4,'tangent','접선 두 개를 갖는 외부 점에서 중심을 이으면 어떤 각이 이등분되나요?','접선 길이와 반지름이 만드는 합동을 이용하고 두 접선 사이 각의 합을 확인하세요.',r'$AC=PC$, $BD=PD$이며 직각삼각형의 합동에서 $OC,OD$는 각 $ACP,BDP$를 각각 이등분합니다.|위아래 접선은 평행하므로 $\angle ACP+\angle BDP=180^\circ$. 삼각형 $COD$의 $C,D$ 각의 합은 $90^\circ$이므로 $\angle COD=90^\circ$입니다.|두 중심각 $\angle AOC,\angle BOD$는 합이 $90^\circ$이지만 각각 같다는 보장은 없습니다.','항상 같은 각과 합만 정해지는 각을 구분했나요?',(4,171,164,326,298))
add(20,r'$PA,PB$는 원의 접선이고 사각형 $APBO$의 넓이는 $16\sqrt3\,cm^2$이다. 중심각 $120^\circ$인 부채꼴 $AOB$의 호의 길이는? ($A,B$는 접점)',r'$2\pi\,cm$|$\frac83\pi\,cm$|$\frac{10}{3}\pi\,cm$|$4\pi\,cm$|$\frac{16}{3}\pi\,cm$',2,'tangent','중심과 외부 점을 잇는 선분이 중심각도 이등분하나요?','두 합동인 직각삼각형의 넓이를 반지름으로 나타내세요.',r'반지름을 $r$라 하면 $\angle AOP=60^\circ$이고 $AP=r\tan60^\circ=\sqrt3r$입니다.|사각형의 넓이는 $2\times\frac12r\cdot\sqrt3r=\sqrt3r^2$이므로 $r=4$입니다.|호의 길이는 $2\pi\times4\times\frac{120}{360}=\frac83\pi\,cm$입니다.','넓이를 구한 뒤 반지름으로 되돌아가 호의 길이를 계산했나요?',(4,164,578,337,698))
add(21,r'원 $O$는 $\angle A=90^\circ$인 직각삼각형 $ABC$의 내접원이며 $D,E,F$는 접점이다. $BE=6\,cm$, $CE=9\,cm$일 때 $OB$의 길이는?',r'$3\sqrt5\,cm$|$3\sqrt7\,cm$|$4\sqrt3\,cm$|$4\sqrt5\,cm$|$5\sqrt2\,cm$',1,'tangent','직각 꼭짓점에서 두 접점까지 길이가 반지름과 같다는 점을 사용할 수 있나요?','두 직각변을 반지름으로 나타내고 큰 삼각형의 피타고라스 정리를 적용하세요.',r'반지름을 $r$라 하면 $AB=r+6$, $AC=r+9$, $BC=15$입니다.|$(r+6)^2+(r+9)^2=15^2$에서 $(r-3)(r+18)=0$, 양의 해는 $r=3$입니다.|직각삼각형 $BOE$에서 $OB=\sqrt{6^2+3^2}=3\sqrt5\,cm$입니다.','반지름 자체가 아니라 중심에서 꼭짓점까지 거리를 구했나요?',(4,151,936,349,1059))
add(22,r'$A,B$는 점 $P$에서 원 $O$에 그은 두 접선의 접점이다. $\angle APB=60^\circ$, $AP=6\,cm$일 때, $\triangle OAB$의 넓이는?',r'$2\sqrt3\,cm^2$|$3\sqrt3\,cm^2$|$4\sqrt3\,cm^2$|$5\sqrt3\,cm^2$|$6\sqrt3\,cm^2$',2,'tangent','접점의 직각을 이용해 중심각과 반지름을 구할 수 있나요?','외부 점에서의 각을 이등분한 직각삼각형에서 반지름을 구하고 넓이 공식에 넣으세요.',r'$\angle APO=30^\circ$이므로 $OA=6\tan30^\circ=2\sqrt3$입니다.|$\angle AOB=180^\circ-60^\circ=120^\circ$입니다.|넓이는 $\frac12(2\sqrt3)^2\sin120^\circ=3\sqrt3\,cm^2$입니다.','사각형 넓이가 아닌 가운데 삼각형 넓이를 구했나요?',(4,549,157,737,279))
add(23,r'$AB$는 원 $O$의 지름이고 $AD,CD,BC$는 접선이다. $AD=4\,cm$, $BC=7\,cm$일 때, 사각형 $ABCD$의 넓이는?',r'$11\sqrt5\,cm^2$|$11\sqrt7\,cm^2$|$22\sqrt5\,cm^2$|$22\sqrt7\,cm^2$|$33\sqrt5\,cm^2$',4,'tangent','위쪽 접선은 두 꼭짓점에서의 접선 길이 합으로 나타낼 수 있나요?','사다리꼴의 평행한 두 변과 그 차로 직각삼각형을 만드세요.',r'$CD=4+7=11\,cm$입니다. 평행한 수직변의 길이 차는 $3\,cm$입니다.|$AB=\sqrt{11^2-3^2}=4\sqrt7\,cm$입니다.|넓이는 $\frac{4+7}{2}\times4\sqrt7=22\sqrt7\,cm^2$입니다.','사다리꼴의 높이가 어느 방향인지 확인했나요?',(4,570,548,724,671))
add(24,r'중심이 같은 두 원에서 한 직선이 큰 원과 만나는 점을 $A,B$, 작은 원과 만나는 점을 $C,D$라 한다. $AB=12\,cm$, $CD=8\,cm$일 때 두 원의 넓이 차는?',r'$4\pi\,cm^2$|$8\pi\,cm^2$|$12\pi\,cm^2$|$16\pi\,cm^2$|$20\pi\,cm^2$',5,'chord','두 현의 중점과 중심 사이의 거리는 같나요?','두 반지름의 제곱을 각각 나타내어 공통 거리의 제곱을 소거하세요.',r'중심에서 직선까지 거리를 $d$, 두 반지름을 $R,r$라 하면 $R^2=d^2+6^2$, $r^2=d^2+4^2$입니다.|따라서 넓이 차는 $\pi(R^2-r^2)=\pi(36-16)=20\pi\,cm^2$입니다.','반지름을 각각 구하지 않고도 제곱의 차를 구할 수 있나요?',(4,575,904,713,1030))
add(25,r'원 $O$에서 $AB\perp OC$, $M=AB\cap OC$이고 $BM=8\,cm$, $CM=4\,cm$일 때, 원의 둘레는?',r'$18\pi\,cm$|$20\pi\,cm$|$22\pi\,cm$|$24\pi\,cm$|$26\pi\,cm$',2,'chord','반지름과 중심에서 현까지의 거리의 차를 읽었나요?','직각삼각형의 피타고라스 식으로 반지름을 구한 뒤 원의 둘레 공식을 쓰세요.',r'반지름을 $r$라 하면 $OM=r-4$입니다. $r^2=(r-4)^2+8^2$에서 $8r=80$, $r=10$입니다.|둘레는 $2\pi r=20\pi\,cm$입니다.','반지름에서 둘레로 변환하는 마지막 연산은 무엇인가요?',(5,169,139,330,300))
add(26,r'$\angle C=90^\circ$, $AC=9\,cm$인 삼각형 $ABC$의 내접원 중심이 $O$, 반지름이 $3\,cm$이다. 접점을 각각 $D,E,F$라 할 때, 사각형 $ODBE$의 넓이는?',r'$21\,cm^2$|$24\,cm^2$|$27\,cm^2$|$30\,cm^2$|$33\,cm^2$',3,'tangent','직각 꼭짓점 근처의 접선 길이와 반지름을 연결했나요?','접선 조각을 문자로 놓고 큰 직각삼각형에서 모르는 조각을 구하세요.',r'$CE=CF=3$, $AD=AF=6$입니다. $BE=BD=t$라 하면 $BC=t+3$, $AB=t+6$입니다.|$(t+6)^2=9^2+(t+3)^2$에서 $6t=54$, $t=9$입니다.|$ODBE$는 높이가 각각 $3$인 두 직각삼각형의 합이므로 넓이는 $2\times\frac12\times9\times3=27\,cm^2$입니다.','같은 넓이의 두 삼각형을 모두 더했나요?',(5,157,565,344,701))
add(27,r'정사각형 안에 반지름이 $2\,cm$인 원 $4$개와 작은 원 $1$개가 그림처럼 꼭 맞게 들어 있다. 작은 원의 반지름은?',r'$\sqrt2\,cm$|$(\sqrt2-1)\,cm$|$(\sqrt2+1)\,cm$|$(2-2\sqrt2)\,cm$|$(2\sqrt2-2)\,cm$',5,'chord','큰 원들의 중심을 연결하면 어떤 정사각형이 되나요?','정사각형의 중심에서 큰 원의 중심까지 거리를 대각선의 절반으로 구하세요.',r'큰 원 중심들이 만드는 정사각형의 한 변은 $4\,cm$입니다. 그 중심에서 한 꼭짓점까지 거리는 $2\sqrt2\,cm$입니다.|작은 반지름을 $r$라 하면 두 원이 외접하므로 $r+2=2\sqrt2$입니다.|따라서 $r=2\sqrt2-2\,cm$입니다.','두 원의 중심 간 거리가 반지름의 합임을 사용했나요?',(5,185,936,315,1066))
add(28,r'그림에서 $O$가 원의 중심이고 길이가 각각 $3\,cm$인 두 호가 이어져 있다. 한 호를 보는 원주각이 $23^\circ$일 때, 두 호 전체의 중심각 $x$의 값은?',r'$46$|$67$|$69$|$92$|$113$',4,'circle','같은 길이의 호가 각각 같은 중심각을 갖나요?','원주각을 중심각으로 바꾼 뒤 같은 두 호에 대한 각을 합하세요.',r'원주각 $23^\circ$가 보는 호의 중심각은 $46^\circ$입니다.|두 호의 길이가 같으므로 각각의 중심각도 같습니다. 따라서 $x=46+46=92$입니다.','각을 두 배 하는 이유가 두 번 나타나는 것을 구분했나요?',(5,564,112,726,290))
add(29,r'작은 호 $AB$의 길이는 원 $O$의 둘레의 $\frac15$이고, $5\widehat{AB}=4\widehat{CD}$이다. 그림에서 두 현 $AC,BD$가 만나는 점의 각 $x$의 크기는?',r'$75^\circ$|$77^\circ$|$79^\circ$|$81^\circ$|$83^\circ$',4,'circle','원의 둘레에 대한 호의 비를 중심각으로 바꿀 수 있나요?','교차하는 두 현이 만드는 각은 마주 보는 두 호의 중심각 합의 절반임을 사용하세요.',r'호 $AB$의 중심각은 $72^\circ$입니다. 호 $CD$는 그 $\frac54$배이므로 중심각은 $90^\circ$입니다.|$x=\frac{72^\circ+90^\circ}{2}=81^\circ$입니다.','원 안의 교차각에서는 두 호를 더한다는 점을 확인했나요?',(5,565,459,721,610))
add(30,r'$PC$는 원 $O$의 접선이고 $C$는 접점이다. $AB$는 지름이며 $P,A,B$는 한 직선 위에 있다. $\angle APC=30^\circ$, $PA=3\,cm$일 때, $\triangle ABC$의 넓이는?',r'$3\,cm^2$|$6\,cm^2$|$\frac{9\sqrt3}{2}\,cm^2$|$6\sqrt3\,cm^2$|$\frac{15\sqrt3}{2}\,cm^2$',3,'tangent','접점에서 반지름이 이루는 직각으로 반지름을 구할 수 있나요?','중심까지의 거리를 반지름과 바깥 길이의 합으로 놓고 특수각을 이용하세요.',r'반지름을 $r$라 하면 $PO=r+3$, $OC=r$입니다. $\sin30^\circ=\frac r{r+3}$에서 $r=3$입니다.|$AB=6$이며 $C$에서 직선 $AB$까지의 높이는 $OC\sin60^\circ=\frac{3\sqrt3}{2}$입니다.|넓이는 $\frac12\times6\times\frac{3\sqrt3}{2}=\frac{9\sqrt3}{2}\,cm^2$입니다.','반지름을 높이로 바로 사용하지 않았나요?',(5,546,815,748,964))
add(31,r'원 $O$는 $\triangle ABC$의 내접원이면서 접점 $D,E,F$를 꼭짓점으로 하는 삼각형의 외접원이다. $\angle B=76^\circ$, $DF=EF$일 때, 작은 호 $EF$에 대한 중심각의 크기는?',r'$104^\circ$|$112^\circ$|$124^\circ$|$128^\circ$|$132^\circ$',4,'tangent','두 접점의 반지름과 꼭짓점이 이루는 사각형에서 중심각을 구할 수 있나요?','접선 두 개의 각으로 남은 호를 구하고 같은 두 현이 같은 두 호를 만든다는 성질을 쓰세요.',r'$\angle DOE=180^\circ-76^\circ=104^\circ$입니다.|나머지 호 $DF$와 $FE$의 중심각 합은 $360^\circ-104^\circ=256^\circ$입니다.|$DF=EF$이므로 두 중심각이 같아 각각 $128^\circ$입니다.','남은 각을 두 부분으로 똑같이 나누면 얼마인가요?',(6,162,184,342,350))
add(32,r'원 $O$의 두 현 $BA,CD$의 연장선의 교점을 $E$, 두 현 $AD,BC$의 연장선의 교점을 $F$라 한다. $\angle E=44^\circ$, $\angle F=40^\circ$, 호 $AD=CD$일 때, $\angle ACD$의 크기는?',r'$24^\circ$|$25^\circ$|$26^\circ$|$27^\circ$|$28^\circ$',1,'circle','같은 두 호를 한 문자로 놓고 두 바깥 각의 조건을 쓸 수 있나요?','두 할선의 바깥 각이 보는 호의 차를 각각 구하고 원 한 바퀴로 합하세요.',r'호 $AD,DC$의 중심각을 각각 $t$라 하면 $\angle E=44^\circ$에서 호 $BC$의 중심각은 $t+88^\circ$입니다.|$\angle F=40^\circ$에서 호 $AB$의 중심각은 $t+80^\circ$입니다.|네 호의 합은 $4t+168^\circ=360^\circ$이므로 $t=48^\circ$입니다. 따라서 $\angle ACD=24^\circ$입니다.','마지막에는 중심각을 원주각으로 바꾸었나요?',(6,156,658,344,838))
add(33,r'원에 내접하는 오각형 $ABCDE$에서 $\angle BOC=50^\circ$, $\angle D=110^\circ$일 때, $\angle EAB$의 크기는?',r'$91^\circ$|$92^\circ$|$93^\circ$|$94^\circ$|$95^\circ$',5,'circle','두 원주각이 보는 호를 합하면 어떤 호가 중복되나요?','각 $A,D$가 보는 호의 합을 원 한 바퀴와 공통 호의 합으로 나타내세요.',r'각 $A,D$가 보는 호를 합하면 원 한 바퀴에 호 $BC$가 한 번 더 포함됩니다.|따라서 $\angle A+\angle D=\frac{360^\circ+50^\circ}{2}=205^\circ$입니다.|$\angle EAB=205^\circ-110^\circ=95^\circ$입니다.','공통 호를 빠뜨리지 않고 각의 합을 구했나요?',(6,550,157,746,334))
add(34,r'직선 $AT$는 원의 접선이고 $A$는 접점이다. $B,C,D$는 원 위의 점이고 접선이 현 $AB,AC$와 이루는 예각은 각각 $45^\circ,31^\circ$이다. 그림의 $x=\angle ACB$, $y=\angle CDB$에 대하여 $x+y$는?',r'$121^\circ$|$122^\circ$|$123^\circ$|$124^\circ$|$125^\circ$',1,'circle','접선과 현의 각을 반대편 원주각으로 옮길 수 있나요?','삼각형의 나머지 각과 내접사각형의 대각 합을 차례로 사용하세요.',r'접선과 현의 각에서 $x=45^\circ$, $\angle ABC=31^\circ$입니다.|$\angle CAB=180^\circ-45^\circ-31^\circ=104^\circ$이므로 내접사각형에서 $y=76^\circ$입니다.|따라서 $x+y=121^\circ$입니다.','삼각형의 각과 사각형의 대각을 구분했나요?',(6,565,655,744,819))
add(35,r'$B,C$는 점 $A$에서 원에 그은 두 접선의 접점이다. 원 위의 점 $D$에 대하여 $BD=CD$, $\angle ABD=116^\circ$일 때, $\angle CAB$의 크기는?',r'$72^\circ$|$74^\circ$|$76^\circ$|$78^\circ$|$80^\circ$',3,'circle','주어진 둔각과 접선-현의 예각을 구분했나요?','접선-현의 각으로 이등변삼각형의 밑각을 구하고 중심각과 접선의 각을 연결하세요.',r'접선과 현의 예각은 $180^\circ-116^\circ=64^\circ$이므로 $\angle BCD=64^\circ$입니다.|$BD=CD$이므로 $\angle CBD=64^\circ$, $\angle BDC=52^\circ$입니다.|작은 호 $BC$의 중심각은 $104^\circ$입니다. 따라서 $\angle CAB=180^\circ-104^\circ=76^\circ$입니다.','접선 두 개의 각은 작은 중심각과 보각이라는 점을 사용했나요?',(7,163,156,344,331))
add(36,r'원 $O$는 $\triangle ABC$의 외접원이고 반지름은 $6\,cm$이다. 호의 길이가 $4\widehat{AB}=5\widehat{BC}$, $3\widehat{BC}=4\widehat{CA}$를 만족할 때, 삼각형의 넓이는?',r'$(9+6\sqrt3)\,cm^2$|$(18+6\sqrt3)\,cm^2$|$(18+9\sqrt3)\,cm^2$|$(27+6\sqrt3)\,cm^2$|$(27+9\sqrt3)\,cm^2$',5,'circle','세 호의 길이비와 중심각의 비를 구할 수 있나요?','중심과 꼭짓점을 이은 세 삼각형의 넓이를 더하세요.',r'호 $AB:BC:CA=5:4:3$이므로 중심각은 각각 $150^\circ,120^\circ,90^\circ$입니다.|중심은 삼각형 안에 있고 각 작은 삼각형의 두 변은 반지름입니다.|넓이는 $\frac12\times6^2(\sin150^\circ+\sin120^\circ+\sin90^\circ)=18(\frac12+\frac{\sqrt3}{2}+1)=27+9\sqrt3\,cm^2$입니다.','각 부분의 높이를 구하지 않고 삼각비로 합할 수 있나요?',(7,164,548,344,711))
add(37,r'$AB$는 원 $O$의 지름이고 $C,D,E$는 원 위의 점이다. $\angle BCE=27^\circ$일 때, $\angle ADC$의 크기는?',r'$54^\circ$|$58^\circ$|$60^\circ$|$63^\circ$|$65^\circ$',4,'circle','지름의 원주각을 포함한 직각삼각형이 있나요?','같은 호를 보는 원주각을 이용하여 다른 삼각형으로 각을 옮기세요.',r'주어진 $\angle BEC=27^\circ$와 같은 호 $BC$를 보는 $\angle BAC=27^\circ$입니다.|$AB$가 지름이므로 $\angle ACB=90^\circ$, $\angle ABC=63^\circ$입니다.|같은 호 $AC$를 보는 $\angle ADC=\angle ABC=63^\circ$입니다.','같은 호를 보는 원주각을 옮긴 뒤 남은 예각을 구하면 얼마인가요?',(7,167,945,338,1100),reason='원문 본문의 BCE=27도는 그림에서 E에 표시된 27도 및 정답과 불일치. BEC=27도로 고쳐 그림과 같은 원주각 문제로 정리.')
# Correct the source's swapped angle name in both problem and its repeated text.
for key in ['question','explanation']:D[5][-1][key]=D[5][-1][key].replace(r'$\angle BCE=27^\circ$',r'$\angle BEC=27^\circ$')
add(38,r'그림에서 $P,A,D$와 $P,B,C$는 각각 한 직선 위에 있다. $\angle P=45^\circ$, $\angle DAC=70^\circ$이고 $A,B,C,D$가 한 원 위에 있을 때, $\angle ADB$의 크기는?',r'$23^\circ$|$24^\circ$|$25^\circ$|$26^\circ$|$27^\circ$',3,'circle','연장선이 만드는 내각과 외각을 구분할 수 있나요?','먼저 바깥 삼각형의 내각을 구하고 같은 호의 원주각으로 옮기세요.',r'$\angle PAC=180^\circ-70^\circ=110^\circ$입니다.|$\triangle PAC$에서 $\angle PCA=180^\circ-45^\circ-110^\circ=25^\circ$입니다.|$P,B,C$가 일직선이므로 $\angle BCA=25^\circ$이며 같은 호 $AB$에 대한 $\angle ADB$도 $25^\circ$입니다.','같은 현을 보는 각을 마지막에 연결했나요?',(7,548,136,745,292))
add(39,r'다음 중 옳은 설명은?',r'수치로 표현된 자료에서 가장 적절한 대표값은 평균이다.|자료의 중앙값은 항상 자료의 변량 중 하나로 정해진다.|자료의 최빈값은 항상 하나로만 정해진다.|평균은 이상점에 매우 민감한 영향을 받지만 중앙값은 이상점에 영향을 덜 받는다.|모든 대표값은 수치로 표현되지 않는 자료에서도 활용할 수 있다.',4,'stats','각 대표값이 자료의 어떤 특징을 나타내는지 알고 있나요?','극단적인 값이 들어간 자료와 짝수 개 자료를 예로 들어 항상 성립하는지 판단하세요.',r'평균이 언제나 가장 적절하지는 않습니다. 자료가 $1,2$이면 중앙값은 $1.5$여서 실제 변량이 아닐 수 있습니다.|최빈값은 여러 개일 수 있습니다. 예를 들어 $1,1,2,2$의 최빈값은 $1,2$입니다. 평균과 중앙값은 수치나 순서가 없는 자료에 모두 적용할 수 없습니다.|극단적인 값을 바꾸면 평균은 크게 변할 수 있지만 중앙값은 순서의 가운데를 사용하여 영향이 상대적으로 작습니다. 따라서 보기 $4$가 참입니다.','어떤 설명이 극단적인 값에 대한 대표값의 반응을 바르게 비교하나요?',reason='원본 보기3의 하나로 정해진다는 표현이 단일 최빈값 주장인지 모호하여 하나로만으로 명확히 함. 최빈값이 여러 개일 수 있다는 취지 및 원본 정답4 유지.')
add(40,r'중학교 $3$학년 학생 $20$명의 $1$분간 팔굽혀펴기 횟수를 나타낸 줄기와 잎 그림이다. 횟수의 중앙값을 $a$회, 최빈값을 $b$회라 할 때, $a+b$의 값은?',r'$18.5$|$19$|$31$|$31.5$|$32$',4,'stats','줄기와 잎을 합쳐 읽은 자료의 개수와 가운데 두 위치를 확인했나요?','전체 자료를 순서대로 읽어 중앙값을 구하고 가장 많이 반복되는 값을 별도로 세세요.',r'자료는 $5,5,6,8,9,9,10,11,14,15,16,16,16,17,17,18,19,23,28,28$입니다.|자료가 $20$개이므로 중앙값은 $10$번째와 $11$번째 값의 평균인 $\frac{15+16}{2}=15.5$입니다.|가장 많이 나온 값은 $16$으로 최빈값입니다. 따라서 $a+b=15.5+16=31.5$입니다.','잎의 숫자만 읽지 않고 줄기의 자리값을 반영했나요?',(7,486,936,804,1058))
add(41,r'다음 자료에서 중앙값과 최빈값이 모두 $7$일 때, $a$의 값은? $a+4,\ 9,\ 7,\ 5,\ 7,\ 10,\ 9,\ 3a+1$',r'$2$|$3$|$4$|$5$|$6$',1,'stats','현재 같은 횟수로 나타나는 두 수를 확인했나요?','최빈값 조건에서 가능한 미지수를 먼저 구한 뒤 중앙값 조건으로 걸러내세요.',r'현재 $7$과 $9$가 각각 두 번씩 나타나므로 최빈값이 $7$이 되려면 미지 항 중 적어도 하나가 $7$이어야 합니다.|$a+4=7$이면 $a=3$, $3a+1=7$이면 $a=2$입니다.|$a=3$일 때 정렬 자료의 가운데는 $7,9$로 중앙값은 $8$입니다. $a=2$일 때 자료는 $5,6,7,7,7,9,9,10$으로 중앙값과 최빈값이 모두 $7$입니다.','한 조건만 만족하는 후보를 제외했나요?')
add(42,r'다음 자료의 평균과 중앙값이 일치할 때, 가능한 $x$의 값들을 모두 더한 값은? $2,\ 0,\ x,\ 4,\ -2$',r'$-3$|$-2$|$1$|$2$|$3$',5,'stats','미지수의 위치에 따라 가운데 값이 달라질 수 있나요?','미지수가 가운데 구간보다 작은 경우, 구간 안인 경우, 큰 경우로 나누세요.',r'평균은 $\frac{x+4}{5}$입니다. $x\le0$이면 중앙값은 $0$이므로 $x=-4$입니다.|$0\le x\le2$이면 중앙값은 $x$이므로 $\frac{x+4}{5}=x$에서 $x=1$입니다.|$x\ge2$이면 중앙값은 $2$이므로 $x=6$입니다. 각각 해당 구간에 속하며 합은 $-4+1+6=3$입니다.','각 경우에서 얻은 해가 그 경우의 범위에 속하나요?')
add(43,r'다음 중 옳지 않은 것은?',r'자료의 변량이 평균에 모여 있을수록 산포도는 작아진다.|각 변량에서 평균을 뺀 값을 그 변량의 편차라고 한다.|편차가 작을수록 그 변량은 평균에 가까이 있다.|편차의 합은 항상 $0$이므로 편차의 평균도 $0$이다.|자료의 표준편차가 더 클수록 그 자료의 변량들은 평균을 중심으로 더 흩어져 있다.',3,'variance','음수인 편차도 있다는 점을 생각했나요?','평균에서의 거리는 부호 있는 수의 대소가 아니라 절댓값이라는 점을 예로 확인하세요.',r'편차는 음수일 수 있습니다. 편차가 $-10$인 값은 편차가 $1$인 값보다 편차 자체는 작지만 평균에서 더 멉니다.|따라서 평균에 가까운지를 판단하려면 편차의 절댓값을 비교해야 합니다. 보기 $3$은 틀리고 나머지는 정의와 성질에 맞습니다.','작다는 표현이 수의 대소인지 거리의 대소인지 구분했나요?')
add(44,r'같은 반 학생 호원이와 평강이의 기말고사 전체 과목 평균이 같다. 두 학생의 표준편차가 각각 $a$점, $b$점일 때, 옳은 것은?',r'호원이와 평강이의 분산은 각각 $\sqrt a,\sqrt b$이다.|$a=1$이면 호원이의 모든 과목 점수의 편차가 $1$이다.|$a<b$이면 호원이의 과목별 점수가 평강이보다 고르다.|$a>b$이면 호원이는 모든 과목에서 평강이보다 편차가 크다.|$a=b$이면 두 학생은 모든 과목 점수가 동일하다.',3,'variance','표준편차는 개별 점수의 차이가 아니라 전체 분포의 어떤 특징을 나타내나요?','분산과 표준편차의 관계, 전체 요약값과 개별 값의 차이를 구분하세요.',r'분산은 각각 $a^2,b^2$이므로 보기 $1$은 틀립니다. 표준편차가 같아도 각 과목 편차가 모두 같지는 않습니다.|표준편차가 작으면 평균 주위에 더 모여 있으므로 $a<b$일 때 호원이의 점수가 더 고릅니다.|표준편차의 대소가 모든 과목 편차의 대소를 뜻하지 않으며 같은 표준편차가 과목별 동일한 점수를 뜻하지도 않습니다.','전체 자료의 흩어짐만을 바르게 해석한 보기는 무엇인가요?')
add(45,r'환자 $5$명의 접수 후 대기 시간에 대한 편차가 표와 같고 평균은 $10$분이었다. 이 환자들의 대기 시간의 표준편차는?',r'$0$분|$\sqrt{10}$분|$5\sqrt2$분|$10$분|$50$분',2,'variance','표의 값이 원래 시간인지 이미 평균을 뺀 편차인지 확인했나요?','편차에 평균을 또 빼지 말고 제곱들의 평균을 구한 후 제곱근을 취하세요.',r'편차는 $5,-2,2,-4,-1$이고 합은 $0$입니다.|분산은 $\frac{5^2+(-2)^2+2^2+(-4)^2+(-1)^2}{5}=\frac{50}{5}=10$입니다.|표준편차는 $\sqrt{10}$분입니다.','분산에서 한 단계 더 계산하여 표준편차를 구했나요?',(8,484,646,806,734))
add(46,r'두 변량 $x$: 겨울철 기온, $y$: 실내 난방 비용 사이의 상관관계를 대체로 나타내는 산점도는?',r'$1$번 산점도|$2$번 산점도|$3$번 산점도|$4$번 산점도|$5$번 산점도',5,'scatter','기온이 올라갈 때 난방에 필요한 비용이 대체로 어떻게 바뀌나요?','한 변량이 증가하고 다른 변량이 감소하는 경향을 그래프의 방향과 연결하세요.',r'겨울 기온이 높으면 대체로 난방 필요가 줄어 난방 비용도 적어집니다.|따라서 음의 상관관계를 나타내는 오른쪽 아래로 기울어진 산점도인 $5$번이 적절합니다.','오른쪽으로 이동할 때 점들의 세로 위치가 어떻게 바뀌나요?',(9,62,192,374,601))
add(47,r'남학생 $15$명, 여학생 $10$명인 학급에서 두 집단의 수학 시험 평균이 같다. 남학생과 여학생 점수의 분산이 각각 $20,10$일 때, 학급 전체 점수의 분산은?',r'$15$|$16$|$18$|$25$|$30$',2,'variance','두 집단의 평균이 같으면 편차의 기준도 같아지나요?','분산에 집단 크기를 곱해 편차 제곱의 합을 구하고 전체 인원으로 나누세요.',r'공통 평균은 전체 평균과 같습니다. 남학생 편차 제곱의 합은 $15\times20=300$, 여학생은 $10\times10=100$입니다.|전체 분산은 $\frac{300+100}{15+10}=16$입니다.','집단 인원이 다르므로 분산을 단순 평균하지 않았나요?')
add(48,r'읽기와 듣기를 각각 $10$점 만점으로 평가하고 두 영역 모두 $8$점 이상이어야 합격하는 시험의 응시자 $15$명 점수를 나타낸 산점도이다. 옳지 않은 설명을 모두 고르면? (정답 $2$개)',r'합격자의 읽기 점수 평균은 $8.75$점이다.|불합격자의 듣기 점수 중앙값은 $4.5$점이다.|전체 응시자 중 합격자의 비율은 $\frac4{15}$이다.|읽기 점수와 듣기 점수가 $4$점 이상 차이 나는 응시자는 없다.|읽기 점수와 듣기 점수 사이에는 양의 상관관계가 있다.',[2,4],'scatter','합격하려면 두 좌표가 동시에 경계값 이상이어야 하나요?','합격점들을 먼저 표시하고 나머지 점들의 듣기 점수를 정렬하세요. 두 점수 차이와 전체 경향은 각각 별도로 확인하세요.',r'합격점은 $(8,9),(8,10),(9,8),(10,9)$로 $4$명입니다. 읽기 평균은 $\frac{8+8+9+10}{4}=8.75$, 비율은 $\frac4{15}$입니다.|불합격자의 듣기 점수는 정렬하면 $2,3,3,4,5,5,6,6,7,8,8$입니다. 중앙값은 $6$번째인 $5$이므로 보기 $2$는 틀립니다.|점 $(9,5)$는 두 점수가 $4$점 차이 나므로 보기 $4$도 틀립니다. 전체적으로는 오른쪽 위로 증가하는 경향이 있어 양의 상관관계입니다.','중앙값의 위치와 차이가 정확히 경계에 해당하는 점을 빠뜨리지 않았나요?',(9,549,202,755,391))

def norm(s):
 s=re.sub(r'\\frac\s*([a-zA-Z0-9])\s*([a-zA-Z0-9])',r'\\frac{\1}{\2}',s)
 return re.sub(r'\\frac\s*([a-zA-Z0-9])\s*(?=\{)',r'\\frac{\1}',s)
def pageof(n):
 return (n-1)//6+1 if n<=30 else 6 if n<=34 else 7 if n<=40 else 8 if n<=45 else 9
for r in D:
 out=B/'authoring'/f'round{r}';(out/'assets').mkdir(parents=True,exist_ok=True);doc=fitz.open(B/'sources/source.pdf')
 assert len(D[r])==24
 for q,m in zip(D[r],M[r]):
  for k in q:q[k]=[norm(v) for v in q[k]] if isinstance(q[k],list) else norm(q[k])
  page=pageof(m['sourceNumber']);m['sourcePage']=page
  doc[page-1].get_pixmap(matrix=fitz.Matrix(1.25,1.25)).save(out/m['sourceImagePath'])
  if m['crop']:
   pn,x0,y0,x1,y1=m['crop'];doc[pn-1].get_pixmap(matrix=fitz.Matrix(3,3),clip=fitz.Rect(x0/1.5,y0/1.5,x1/1.5,y1/1.5)).save(out/m['imagePath'])
 (out/'questions.json').write_text(json.dumps({'questions':D[r]},ensure_ascii=False,indent=2)+'\n')
 (out/'manifest.json').write_text(json.dumps(dict(round=r,unitId='reg_1781420075936_chap_1781420292103_unit_'+U[r],sourceTitle='중3 모의고사(01) 삼각비,원,통계 - '+('홀수' if r==5 else '짝수')+' 문항',questions=M[r]),ensure_ascii=False,indent=2)+'\n')
 print('round',r,'questions',len(D[r]),'images',sum(bool(m['imagePath']) for m in M[r]))
(B/'questions.json').write_text(json.dumps({'questions':D[5]+D[6]},ensure_ascii=False,indent=2)+'\n')
